{"code": "
s = input().strip()

# Find all lucky substrings
lucky_substrings = set()

# A substring is lucky if it contains only '4' and '7'
def is_lucky(sub):
    return all(c in {'4', '7'} for c in sub)

# Find all lucky substrings
for i in range(len(s)):
    for j in range(i + 1, len(s) + 1):
        substr = s[i:j]
        if is_lucky(substr):
            lucky_substrings.add(substr)

if not lucky_substrings:
    print(-1)
else:
    # Count occurrences of each lucky substring
    from collections import defaultdict
    count = defaultdict(int)

    # Count occurrences
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substr = s[i:j]
            if substr in lucky_substrings:
                count[substr] += 1

    # Find the maximum count
    max_count = max(count.values())

    # Find all substrings with max_count
    candidates = [k for k, v in count.items() if v == max_count]

    # Find lexicographically smallest
    result = min(candidates)
    print(result)
"}

