import sys

def sum_of_digits(x):
    """Return the sum of digits of x"""
    return sum(int(d) for d in str(x))

def solve():
    n = int(sys.stdin.readline())

    # Find all x such that x + sum_of_digits(x) = n
    # x must be less than n, and sum_of_digits(x) is at most 9 * number_of_digits(n)
    # So x >= n - 9 * number_of_digits(n)

    # Use a reasonable upper bound for the sum of digits (e.g., 100)
    valid_x = []
    for x in range(n - 100, n):
        if x + sum_of_digits(x) == n:
            valid_x.append(x)

    # Output results
    print(len(valid_x))
    for x in valid_x:
        print(x)

if __name__ == "__main__":
    solve()
"}

