n, m, k = map(int, input().split())
grid = [[False for _ in range(m)] for _ in range(n)]

for move in range(1, k + 1):
    i, j = map(int, input().split())
    i -= 1  # Convert to 0-indexed
    j -= 1

    grid[i][j] = True

    # Check if this completes any 2x2 square
    # A 2x2 square is completed if all four corners are black

    # Check square with top-left corner at (i-1, j-1)
    if i > 0 and j > 0:
        if grid[i-1][j-1] and grid[i-1][j] and grid[i][j-1]:
            print(move)
            exit()

