def solve():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    b = []
    state_str = next(it)
    for c in state_str:
        b.append(1 if c == '1' else 0)

    # Build the matrix
    cols = [[] for _ in range(k)]  # cols[j] contains indices of lamps in subset j
    for j in range(k):
        c = int(next(it))
        for _ in range(c):
            lamp = int(next(it)) - 1  # 0-indexed
            cols[j].append(lamp)

    # Build the incidence matrix (n rows, k cols)
    # We'll solve for each prefix

    # Gaussian elimination modulo 2 for each prefix

    def solve_prefix(i):
        """Solve for prefix 0..i-1"""
        # Build the matrix for lamps 0..i-1
        mat = []
        rhs = []
        for lamp in range(i):
            # Equation: sum_{j in cols} x_j ≡ a_lamp (mod 2)
            # where a_lamp = 1 if b[lamp] == 0 (needs odd number of toggles)
            row = [0] * k
            for j in cols:
                if lamp in j:
                    row[j] = 1
            mat.append(row)
            rhs.append(1 if b[lamp] == 0 else 0)

        # Perform Gaussian elimination modulo 2
        rank = 0
        for col in range(k):
            pivot = -1
            for row in range(rank, i):
                if mat[row][col]:
                    pivot = row
                    break
            if pivot == -1:
                continue
            mat[rank], mat[pivot] = mat[pivot], mat[rank]
            rhs[rank], rhs[pivot] = rhs[pivot], rhs[rank]

            for row in range(k):
                if row != rank and mat[row][col]:
                    for c in range(col, k):
                        mat[row][c] ^= mat[rank][c]
                    rhs[row] ^= rhs[rank]
            rank += 1

        # Check if the system is consistent
        for row in range(rank, i):
            if rhs[row]:
                return -1  # Not possible (should never happen given problem guarantees)

        # Back substitution
        x = [0] * k
        for row in range(rank - 1, -1, -1):
            # Find pivot column
            pivot_col = -1
            for c in range(k):
                if mat[row][c]:
                    pivot_col = c
                    break
            if pivot_col == -1:
