import math

def count_good_pairs(l, r, x, y):
    if y % x != 0:
        return 0

    N = y // x
    count = 0

    for d in range(1, int(math.isqrt(N)) + 1):
        if N % d == 0:
            complement = N // d
            if math.gcd(d, complement) == 1:
                a1 = x * d
                b1 = x * complement

                if l <= a1 <= r and l <= b1 <= r:
                    if d == complement:
                        count += 1
                    else:
                        count += 2

    return count

