def is_horizontal(segment):
    """Check if a segment is horizontal"""
    x1, y1, x2, y2 = segment
    return y1 == y2

def is_vertical(segment):
    """Check if a segment is vertical"""
    x1, y1, x2, y2 = segment
    return x1 == x2

def get_horizontal_y(segment):
    """Get the y-coordinate of a horizontal segment"""
    x1, y1, x2, y2 = segment
    return y1

def get_vertical_x(segment):
    """Get the x-coordinate of a vertical segment"""
    x1, y1, x2, y2 = segment
    return x1

# Read the four segments
segments = []
for _ in range(4):
    x1, y1, x2, y2 = map(int, input().split())
    segments.append((x1, y1, x2, y2))

# Separate into horizontal and vertical segments
horizontal_segments = []
vertical_segments = []
for segment in segments:
    if is_horizontal(segment):
        horizontal_segments.append(segment)
    elif is_vertical(segment):
        vertical_segments.append(segment)

# Check if we have exactly 2 horizontal and 2 vertical segments
if len(horizontal_segments) != 2 or len(vertical_segments) != 2:
    print("NO")
    exit()

# Check if horizontal segments have the same y-coordinate
h_y = get_horizontal_y(horizontal_segments[0])
for segment in horizontal_segments[1:]:
    if get_horizontal_y(segment) != h_y:
        print("NO")
        exit()

# Check if vertical segments have the same x-coordinate
v_x = get_vertical_x(vertical_segments[0])
for segment in vertical_segments[1:]:
    if get_vertical_x(segment) != v_x:
        print("NO")
        exit()

# Check if the endpoints match up correctly
# Get the endpoints of horizontal segments
h1_start = (horizontal_segments[0][0], h_y)
if horizontal_segments[0][1] == h_y:
    h1_end = (horizontal_segments[0][2], h_y)
else:
    h1_end = (horizontal_segments[0][0], horizontal_segments[0][1])

h2_start = (horizontal_segments[1][0], h_y)
if horizontal_segments[1][1] == h_y:
    h2_end = (horizontal_segments[1][2], h_y)
else:
    h2_end = (horizontal_segments[1][0], horizontal_segments[1][1])

# Get the endpoints of vertical segments
v1_start = (v_x, vertical_segments[0][1])
if vertical_segments[0][0] == v_x:
