import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    l = int(data[0])
    r = int(data[1])
    k = int(data[2])

    result = []
    power = 1  # k^0

    while power <= r:
        if power >= l:
            result.append(power)
        # Prevent infinite loop (though k >= 2 so not needed)
        if power > r // k:
            break
        power *= k

    if not result:
        print(-1)
    else:
        for num in result:
            print(num)

if __name__ == "__main__":
    solve()
"}

