                    # with one of them being the midpoint of the arc

                    # Calculate the angles of the triangle
                    a = points[i]
                    b = points[j]
                    c = points[k]

                    # Calculate angles at each point
                    # Using Law of Cosines
                    ab = distance(a, b)
                    ac = distance(a, c)
                    bc = distance(b, c)

                    # Angle at a
                    cos_a = (ab**2 + ac**2 - bc**2) / (2 * ab * ac)
                    if abs(cos_a) > 1.0 + 1e-9:
                        cos_a = 1.0
                    elif abs(cos_a) < -1.0 - 1e-9:
                        cos_a = -1.0
                    angle_a = math.acos(cos_a)

                    # Angle at b
                    cos_b = (ab**2 + bc**2 - ac**2) / (2 * ab * bc)
                    if abs(cos_b) > 1.0 + 1e-9:
