import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # dp[l][r] = maximum points for subarray a[l..r]
    dp = [[0] * n for _ in range(n)]

    # Fill dp for subarrays of length 1
    for i in range(n):
        dp[i][i] = a[i]

    # Fill dp for subarrays of length > 1
    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1

            # dp[l][r] = max over all i in [l, r] of (dp[l][i-1] + dp[i+1][r] + a[i])
            max_points = 0
            for i in range(l, r + 1):
                # Handle left subarray boundary
                if i == l:
                    left = 0
                else:
                    left = dp[l][i-1]

                # Handle right subarray boundary
                if i == r:
                    right = 0
                else:
                    right = dp[i+1][r]

                points = left + right + a[i]
                max_points = max(max_points, points)

            dp[l][r] = max_points

    print(dp[0][n-1])

if __name__ == "__main__":
    solve()
