def is_lucky_string_valid(s):
    """Check if a string is lucky"""
    last_pos = {}
    n = len(s)

    for i in range(n):
        c = s[i]
        if c in last_pos:
            if abs(i + 1 - last_pos[c]) not in {4, 7}:
                return False
        last_pos[c] = i + 1
    return True

def find_lucky_string(n):
    """Find the lexicographically minimal lucky string of length n"""
    last_pos = {}
    result = []

    for i in range(n):
        # Try each letter from 'a' to 'z'
        for c in range(ord('a'), ord('z') + 1):
            c_char = chr(c)
            if c_char in last_pos:
                if abs(i + 1 - last_pos[c_char]) in {4, 7}:
                    # Valid, use this letter
                    result.append(c_char)
                    last_pos[c_char] = i + 1
                    break
            else:
                # Not used before, always valid
                result.append(c_char)
                last_pos[c_char] = i + 1
                break

    return ''.join(result)

# Read input
