def solve():
    n = int(input())
    p = list(map(int, input().split()))

    # Build adjacency lists
    # For Qingshan (smaller values)
    # For Daniel (larger values)

    # But actually, we need to simulate the game

    # Let's try a simple approach: for each (x, y), simulate the game

    def qingshan_wins(x, y):
        # Qingshan's turn
        # Find all positions q where |q-x|=1, q!=y, p[q]<p[x]
        moves = []
        for q in [x-1, x+1]:
            if 1 <= q <= n and q != y and p[q-1] < p[x-1]:
                moves.append(q)

        # If no moves, Daniel wins
        if not moves:
            return False

        # Daniel's turn
        # Find all positions d where |d-y|=1, d!=x, p[d]>p[y]
        for d in [y-1, y+1]:
            if 1 <= d <= n and d != x and p[d-1] > p[y-1]:
                # Daniel moves to d, now Qingshan's turn
                if not qingshan_wins(q, d):
                    return True

        return False

    answer = 0
    for x in range(1, n+1):
        # Try all possible y for Daniel
        for y in range(1, n+1):
            if x == y:
                continue
            if qingshan_wins(x, y):
                answer += 1
                break  # Only count one valid y per x

    print(answer)

solve()
