def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read grid
    grid = []
    idx = 2
    for i in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # Find connected components of '.' cells
    component_id = [[-1 for _ in range(m)] for _ in range(n)]
    current_id = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and component_id[i][j] == -1:
                # Start BFS for this component
                from collections import deque
                q = deque([(i, j)])
                component_id[i][j] = current_id
                size = 1

                while q:
                    x, y = q.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and component_id[nx][ny] == -1:
                            component_id[nx][ny] = current_id
                            q.append((nx, ny))
                            size += 1

                current_id += 1

    # For each '*' cell, find which component it would join
    result = []
    for i in range(n):
        row_result = []
        for j in range(m):
            if grid[i][j] == '.':
                row_result.append('.')
            else:
                # Find component that would include this cell if it were '.'
                # We need to check all adjacent cells
                component = -1
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                        component = component_id[nx][ny]
                        break

                # Find size of this component
                if component != -1:
                    # Count all cells with this component ID
                    count = 0
                    for x in range(n):
                        for y in range(m):
                            if component_id[x][y] == component:
                                count += 1
                    row_result.append(str(count % 10))
                else:
                    # No adjacent '.' cells, component size is 1 (itself)
                    row_result.append('1')

        result.append(''.join(row_result))

    print('\n'.join(result))

if __name__ == '__main__':
    solve()
