def compute_max_similarity_score(A, B):
    """Compute the maximum similarity score for substrings of A and B"""
    n, m = len(A), len(B)

    # DP table: dp[i][j] = maximum score for substrings ending at A[i] and B[j]
    dp = [[-float('inf')] * m for _ in range(n)]

    # Initialize for single characters
    for i in range(n):
        for j in range(m):
            if A[i] == B[j]:
                score = 4 * 1 - 1 - 1  # LCS = 1, |C| = 1, |D| = 1
                dp[i][j] = score

    # Extend substrings
    for i in range(n):
        for j in range(m):
            if A[i] == B[j]:
                # Extend from left (A[0:i], B[0:j-1] -> A[0:i+1], B[0:j])
                if i > 0 and j > 0:
                    # Take best score from dp[i-1][j-1]
                    score = dp[i-1][j-1] + 4 - 2
                    dp[i][j] = max(dp[i][j], score)

                # Extend from top (A[0:i-1], B[0:j] -> A[0:i], B[0:j+1])
                if i > 0 and j < m - 1:
                    score = dp[i-1][j] + 4 - 2
                    dp[i][j] = max(dp[i][j], score)

                # Extend from diagonal (A[0:i-1], B[0:j-1] -> A[0:i], B[0:j])
                if i > 0 and j > 0:
                    score = dp[i-1][j-1] + 4 - 2
                    dp[i][j] = max(dp[i][j], score)

    return max(max(row) for row in dp)

