def get_position(path, i):
    x, y = 0, 0
    for j in range(i):
        dx, dy = 0, 0
        if path[j] == 'N':
            dy = 1
        elif path[j] == 'S':
            dy = -1
        elif path[j] == 'E':
            dx = 1
        elif path[j] == 'W':
            dx = -1
        x += dx
        y += dy
    return (x, y)

# Find all positions reachable from start in different steps
positions1 = []
positions2 = []

# Reach positions in 0 steps (start)
positions1.append((0, 0))
positions2.append((0, 0))

# Reach positions in 1 step
x1, y1 = get_position(path1, 1)
positions1.append((x1, y1))
x2, y2 = get_position(path2, 1)
positions2.append((x2, y2))

# Reach positions in 2 steps
x1, y1 = get_position(path1, 2)
positions1.append((x1, y1))
x2, y2 = get_position(path2, 2)
positions2.append((x2, y2))

# Find all positions reachable from start in different steps
reachable1 = {0: {(0, 0)}}
reachable2 = {0: {(0, 0)}}

for steps in range(1, n):
    # Get position reached from start in 'steps' steps
    x1, y1 = get_position(path1, steps)
    x2, y2 = get_position(path2, steps)

    # Add to reachable positions
    reachable1[steps] = {(x1, y1)}
    reachable2[steps] = {(x2, y2)}

    # Also consider positions reachable from previous positions
    # We can move both marbles from any reachable position
    for prev_steps, prev_positions in reachable1.items():
        for (px1, py1) in prev_positions:
            # Move forward from position prev_steps to prev_steps+1
            if prev_steps + 1 < n:
                # Move both marbles forward
                nx1, ny1 = get_position(path1, prev_steps + 1)
                nx2, ny2 = get_position(path2, prev_steps + 1)
                reachable1[prev_steps + 1].add((nx1, ny1))
                reachable2[prev_steps + 1].add((nx2, ny2))

# Now check if there's a common position reached at the same time
for steps, positions in reachable1.items():
    if steps in reachable2:
        for (x1, y1) in positions:
            for (x2, y2) in reachable2[steps]:
                if (x1, y1) == (x2, y2):
                    print("YES")
                    exit()

print("NO")
