def solve():
    # Read input
    n, k = map(int, input().split())
    s = input().strip()

    # Parse subsets
    subsets = []
    for _ in range(k):
        c = int(input())
        elements = list(map(int, input().split()))
        subsets.append(elements)

    # Find which subsets contain each lamp
    contains = [[] for _ in range(n + 1)]  # 1-indexed
    for idx, subset in enumerate(subsets):
        for lamp in subset:
            contains[lamp].append(idx)

    # We'll apply subsets greedily for each prefix
    result = []

    for i in range(1, n + 1):
        # Current state of the first i lamps
        state = [int(bit) for bit in s[:i]]
        used = [False] * k
        count = 0

        # Apply subsets to make all first i lamps on
        # Greedy approach: apply subsets that affect lamps that are off
        # But we need to be careful about overlaps

        # First, apply subsets that affect lamps that are off and have only one subset
        for lamp in range(1, i + 1):
            if state[lamp - 1] == 0:
                # Find subsets that contain this lamp
                for subset_idx in contains[lamp]:
                    if not used[subset_idx]:
                        # Apply this subset
                        for j in range(len(subsets[subset_idx])):
                            state[subsets[subset_idx][j] - 1] ^= 1
                        used[subset_idx] = True
                        count += 1
                        break

        # Now check if any lamp is still off (shouldn't be, but just in case)
        for lamp in range(1, i + 1):
            if state[lamp - 1] == 0:
                # Apply both subsets that contain this lamp (if exists)
                if len(contains[lamp]) == 2:
                    for subset_idx in contains[lamp]:
                        if not used[subset_idx]:
