from collections import defaultdict, deque

def has_cycle(graph, n):
    """Check if there's a cycle in the directed graph."""
    in_degree = [0] * (n + 1)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    visited = 0
    while queue:
        u = queue.popleft()
        visited += 1
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return visited != n

def topological_sort(graph, n):
    """Get topological order of vertices."""
    in_degree = [0] * (n + 1)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return order

def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    idx = 0
    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        directed_graph = defaultdict(list)

        edges = []
        for _ in range(m):
            t_i = int(data[idx])
            x_i = int(data[idx + 1])
            y_i = int(data[idx + 2])
            idx += 3

            if t_i == 1:
                directed_graph[x_i].append(y_i)

            edges.append((t_i, x_i, y_i))

        if has_cycle(directed_graph, n):
            results.append("NO")
        else:
            order = topological_sort(directed_graph, n)
            results.append("YES")

            for t_i, x_i, y_i in edges:
                if t_i == 0:
                    # Direct from lower to higher in topological order
                    if order.index(x_i) < order.index(y_i):
                        results.append(f"{x_i} {y_i}")
                    else:
                        results.append(f"{y_i} {x_i}")
                else:
                    results.append(f"{x_i} {y_i}")

    sys.stdout.write("\n".join(results))

solve()
