def solve():
    MOD = 998244353
    x = input().strip()
    y = input().strip()

    # dp[i][j][last_char] = number of ways to interleave first i of x and first j of y
    # into a chaotic string, ending with last_char (or None for empty)
    MAX = 27  # 26 letters + None
    # Use an array of arrays for efficiency
    # dp[i][j] will be an array of size MAX, where dp[i][j][k] represents the count
    dp = [[[-1 for _ in range(MAX)] for __ in range(len(y)+1)] for ___ in range(len(x)+1)]

    # Initialize: empty string
    dp[0][0][0] = 1  # Index 0 represents None

    for i in range(len(x)+1):
        for j in range(len(y)+1):
            for k in range(MAX):
                if i == 0 and j == 0:
                    continue  # already initialized

                # Try appending from x[i-1]
                if i > 0:
                    next_char_index = ord(x[i-1]) - ord('a') + 1  # 1-26 for 'a'-'z', 0 for None
                    if dp[i-1][j][k] >= 0:
                        if k == 0 or next_char_index != k:
                            dp[i][j][next_char_index] = (dp[i][j][next_char_index] + dp[i-1][j][k]) % MOD

                # Try appending from y[j-1]
                if j > 0:
                    next_char_index = ord(y[j-1]) - ord('a') + 1
                    if dp[i][j-1][k] >= 0:
                        if k == 0 or next_char_index != k:
                            dp[i][j][next_char_index] = (dp[i][j][next_char_index] + dp[i][j-1][k]) % MOD

    # Sum all non-empty interleavings
    answer = 0
    for i in range(1, len(x)+1):
        for j in range(1, len(y)+1):
            answer = (answer + dp[i][j][0]) % MOD  # 0 represents None (but we need last character? Actually we sum all last characters)
            for k in range(1, MAX):
                answer = (answer + dp[i][j][k]) % MOD

    print(answer)

