def solve():
    # Read input
    n, m, k = map(int, input().split())

    # Read planets
    planets = []
    for _ in range(n):
        name = input().strip()
        planet = {"name": name, "items": []}
        for _ in range(m):
            a, b, c = map(int, input().split())
            planet["items"].append((a, b, c))  # (buy_price, sell_price, quantity)
        planets.append(planet)

    max_profit = 0

    # Try all pairs of planets
    for buy_planet in planets:
        for sell_planet in planets:
            if buy_planet["name"] == sell_planet["name"]:
                continue

            # Create items for knapsack
            items = []
            for j in range(m):
                a = buy_planet["items"][j][0]
                b = sell_planet["items"][j][1]
                c = buy_planet["items"][j][2]
                profit = b - a
                if profit > 0:  # Only consider profitable items
                    items.append((1, profit, min(k, c)))  # (weight, value, quantity)

            # Knapsack DP
            dp = [0] * (k + 1)
            for weight, value, quantity in items:
                for cap in range(k, weight - 1, -1):
                    for qty in range(1, quantity + 1):
                        if cap - qty >= 0:
                            dp[cap] = max(dp[cap], dp[cap - qty] + qty * value)

            max_profit = max(max_profit, dp[k])

    print(max_profit)

solve()
