def max_square_divisor(y):
    """Find the largest square divisor of y"""
    # Factorize y
    factor = {}
    temp = y

    # Check for 2
    if temp % 2 == 0:
        count = 0
        while temp % 2 == 0:
            temp //= 2
            count += 1
        factor[2] = count

    # Check for odd factors
    for i in range(3, int(temp**0.5) + 1, 2):
        if temp % i == 0:
            count = 0
            while temp % i == 0:
                temp //= i
                count += 1
            factor[i] = count

    # If remaining temp is > 1, it's a prime factor
    if temp > 1:
        factor[temp] = 1

    # Calculate largest square divisor
    d = 1
    for prime, exp in factor.items():
        d *= prime**(exp // 2)
    return d

a, n = map(int, input().split())
result = 0

for year in range(a, a + n):
    d = max_square_divisor(year)
    result += year // d

print(result)
