{"code": "
def find_suffix(line: str, k: int) -> str:
    """Find the suffix starting from the k-th vowel (counting from the end)"""
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Find all vowel positions from the end
    vowel_positions = []
    for i, char in enumerate(reversed(line)):
        if char in vowels:
            vowel_positions.append(len(line) - i)
        if len(vowel_positions) == k:
            break

    if len(vowel_positions) < k:
        return None  # Cannot rhyme

    # Return the suffix starting from the k-th vowel from the end
    return line[vowel_positions[-1]:]

def get_rhyme_pattern(quatrain: list, k: int) -> str:
    """Determine the rhyme pattern for a quatrain"""
    suffixes = []

    for line in quatrain:
        suffix = find_suffix(line, k)
        if suffix is None:
            return "NO"
        suffixes.append(suffix)

    # Check if all lines rhyme
    if all(suffix == suffixes[0] for suffix in suffixes):
        return "aaaa"

    # Check for aabb
    if suffixes[0] == suffixes[1] and suffixes[2] == suffixes[3]:
        return "aabb"

    # Check for abab
    if suffixes[0] == suffixes[2] and suffixes[1] == suffixes[3]:
        return "abab"

    # Check for abba
    if suffixes[0] == suffixes[3] and suffixes[1] == suffixes[2]:
        return "abba"

    return "NO"

def main():
    n, k = map(int, input().split())
    poem = []

    for _ in range(4 * n):
        poem.append(input().strip())

    rhyme_pattern = None

    for i in range(n):
        start_idx = i * 4
        quatrain = poem[start_idx:start_idx + 4]
        pattern = get_rhyme_pattern(quatrain, k)

        if pattern == "NO":
            print("NO")
            return

        if i == 0:
            rhyme_pattern = pattern
        else:
            if rhyme_pattern != pattern:
                print("NO")
                return

    print(rhyme_pattern)

if __name__ == "__main__":
    main()
