        return "aabb"

    # Check for abab
    if suffixes[0] == suffixes[2] and suffixes[1] == suffixes[3]:
        return "abab"

    # Check for abba
    if suffixes[0] == suffixes[3] and suffixes[1] == suffixes[2]:
        return "abba"

    return "NO"

def is_compatible(current_pattern: str, new_pattern: str) -> bool:
    """Check if two patterns are compatible"""
    if current_pattern == "NO":
        return False

    # aaaa is compatible with any pattern
    if current_pattern == "aaaa":
        return True

    if new_pattern == "NO":
        return False

    # Check if new pattern is compatible with current pattern
    if current_pattern == "aabb":
        # aabb: 1=2, 3=4
        return (new_pattern == "aabb" or 
                new_pattern == "abab" or 
                new_pattern == "abba")

    if current_pattern == "abab":
        # abab: 1=2, 3=4
        return (new_pattern == "aabb" or 
                new_pattern == "abab" or 
                new_pattern == "abba")

    if current_pattern == "abba":
        # abba: 1=2, 3=4
        return (new_pattern == "aabb" or 
                new_pattern == "abab" or 
