def find_s_i(a_i):
    """Find a perfect square s_i such that s_i^2 - s_{i-1}^2 = a_i"""
    for d1 in range(1, int(math.sqrt(a_i)) + 1):
        if a_i % d1 == 0:
            d2 = a_i // d1
            if d1 % 2 == d2 % 2 and d2 > d1:
                return (d1 + d2) // 2
    return None

n = int(sys.stdin.readline())
