# Process each odd index i (1, 3, 5, ...)
for i in range(1, n, 2):
    a_i_plus_1 = even_values[i // 2]  # a_2, a_4, ..., a_n are given

    # Find s_{i+1} such that s_{i+1}^2 - s_i^2 = a_i_plus_1
    # This means s_{i+1}^2 = s_i^2 + a_i_plus_1
    found = False

    for d1 in range(1, int(math.sqrt(a_i_plus_1)) + 1):
        if a_i_plus_1 % d1 == 0:
            d2 = a_i_plus_1 // d1
            if d1 % 2 == d2 % 2 and d2 > d1:
                s[i + 1] = (d1 + d2) // 2
                found = True
