            d2 = a_i_minus_1 // d1
            if d1 % 2 == d2 % 2 and d2 > d1:
                s[i] = (d1 + d2) // 2
                found = True
                break

    if not found:
        print("No")
        exit()

# Reconstruct the sequence
result = []
for i in range(1, n + 1):
