import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    operations = []
    for _ in range(m):
        parts = list(map(int, sys.stdin.readline().split()))
        operations.append(parts)

    # Process operations in reverse order
    array = [0] * n

    for i in range(m - 1, -1, -1):
        op = operations[i]
        if op[0] == 1:  # Type 1: add di to [li, ri]
            li, ri, di = op[1], op[2], op[3]
            # We need to undo this addition, so we subtract di from the range
            for j in range(li - 1, ri):
                array[j] -= di
        else:  # Type 2: max of [li, ri] is mi
            li, ri, mi = op[1], op[2], op[3]
            # Find the maximum value in the range
            current_max = max(array[li - 1:ri])
            # If current max is less than mi, we need to increase some values
            # Set all elements in this range to mi, but we should only set those that are less than mi
            for j in range(li - 1, ri):
                if array[j] < mi:
                    array[j] = mi

    # Verify the solution
    valid = True
    array_copy = array[:]
    for op in operations:
        if op[0] == 1:
            li, ri, di = op[1], op[2], op[3]
            for j in range(li - 1, ri):
                array_copy[j] += di
        else:
            li, ri, mi = op[1], op[2], op[3]
            current_max = max(array_copy[li - 1:ri])
            if current_max != mi:
                valid = False
                break

    if valid:
        print("YES")
        print(' '.join(map(str, array)))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
