# Calculate the magic constant s
s = sum(numbers) // n

# Create a matrix to hold the magic square
magic_square = [[0] * n for _ in range(n)]

# Track which numbers we've used
used = [False] * len(numbers)

# Try to fill the magic square
found = False

# Backtracking function
def backtrack(pos):
    global found

    if found:
        return

    if pos == n * n:
        # Check all constraints
        # Check rows
        for i in range(n):
            if sum(magic_square[i]) != s:
                return

        # Check columns
        for j in range(n):
            if sum(magic_square[i][j] for i in range(n)) != s:
                return

        # Check diagonals
        if sum(magic_square[i][i] for i in range(n)) != s:
            return

        if sum(magic_square[i][n-1-i] for i in range(n)) != s:
            return

        found = True
        return


    row = pos // n
    col = pos % n

    # Try placing each unused number
    for i in range(len(numbers)):
        if not used[i]:
            # Check if placing numbers[i] would violate constraints
            # Check row sum (if we've filled all other positions in this row)
            if col == n - 1:
                row_sum = sum(magic_square[row]) + numbers[i]
                if row_sum != s:
                    continue

            # Check column sum (if we've filled all other positions in this column)
            if row == n - 1:
                col_sum = sum(magic_square[i][col] for i in range(n)) + numbers[i]
                if col_sum != s:
                    continue

            # Check main diagonal (if we've filled all other positions in this diagonal)
            if row == col:
                if col == n - 1:
                    diag1_sum = sum(magic_square[i][i] for i in range(n)) + numbers[i]
                    if diag1_sum != s:
                        continue

            # Check secondary diagonal (if we've filled all other positions in this diagonal)
            if row + col == n - 1:
                if col == n - 1:
                    diag2_sum = sum(magic_square[i][n-1-i] for i in range(n)) + numbers[i]
