def solve():
    s = input().strip()
    t = input().strip()

    # If s has fewer characters than t and s is a prefix of t, no permutation can be greater
    if len(s) < len(t) and s == t[:len(s)]:
        print(-1)
        return

    # Sort characters of s to get the smallest permutation
    chars = sorted(s)

    # Try to construct the answer
    result = []
    used = [False] * len(chars)

    def backtrack(pos):
        # If we've used all characters, check if the result is valid
        if pos == len(chars):
            # Check if the constructed string is greater than t
            constructed = ''.join(result)
            if constructed > t:
                return True
            return False

        # Try each character
        for i in range(len(chars)):
            if not used[i]:
                # Try to place this character at position pos
                if len(result) < len(t) and result == t[:len(result)]:
                    # If we're matching t up to this point, we need the next character to be greater
                    if chars[i] > t[len(result)]:
                        result.append(chars[i])
                        used[i] = True
                        if backtrack(pos + 1):
                            return True
                        result.pop()
                        used[i] = False
                else:
                    # Otherwise, any character works
                    result.append(chars[i])
                    used[i] = True
                    if backtrack(pos + 1):
                        return True
                    result.pop()
                    used[i] = False

        return False

    if backtrack(0):
        print(''.join(result))
    else:
        print(-1)

solve()
