    # Build adjacency list for each position
    adj = defaultdict(list)
    for i in range(n):
        if i > 0:
            adj[i].append(i - 1)
        if i < n - 1:
            adj[i].append(i + 1)

    # For each position, find valid moves
    def get_moves(pos, blocked):
        moves = []
        for neighbor in adj[pos]:
            if neighbor != blocked and p[neighbor] < p[pos]:
                moves.append(neighbor)
        return moves

    # BFS from terminal states
    visited = [[False] * n for _ in range(n)]
    result = [[-1] * n for _ in range(n)]

    # Terminal states: when a player can't move
    # Qingshan can't move from (x, y) if she has no valid moves
    # Daniel can't move from (x, y) if he has no valid moves

    # If Qingshan can't move from (x, y), Daniel wins
    for x in range(n):
        for y in range(n):
            if x == y:
                continue
            if not get_moves(x, y):
                # Qingshan can't move, Daniel wins
                result[x][y] = 1  # Daniel wins
                visited[x][y] = True
                queue.append((x, y, 0))  # Qingshan's turn

    # If Daniel can't move from (x, y), Qingshan wins
    for x in range(n):
        for y in range(n):
            if x == y:
                continue
            if not get_moves(y, x):
                # Daniel can't move, Qingshan wins
                result[x][y] = 0  # Qingshan wins
                visited[x][y] = True
                queue.append((x, y, 1))  # Daniel's turn

    # BFS to determine winning positions
    while queue:
        x, y, turn = queue.popleft()

        if turn == 0:  # Qingshan's turn
            for move in get_moves(x, y):
                nx, ny = move, y
                if not visited[nx][ny]:
                    visited[nx][ny] = True
                    result[nx][ny] = 1 - result[x][y]  # Opposite player wins
                    queue.append((nx, ny, 1))
        else:  # Daniel's turn
            for move in get_moves(y, x):
                nx, ny = x, move
                if not visited[nx][ny]:
                    visited[nx][ny] = True
                    result[nx][ny] = 1 - result[x][y]
                    queue.append((nx, ny, 0))

    # Count how many x values make Qingshan win
    answer = 0
    for x in range(n):
        for y in range(n):
            if x == y:
                continue
            if result[x][y] == 0:
                answer += 1

    print(answer)

