n = int(input())
a = list(map(int, input().split()))

# Count frequency of each number
counter = {}
for num in a:
    if num in counter:
        counter[num] += 1
    else:
        counter[num] = 1

# Use a max heap to always pick the number with the highest value
import heapq
heap = []
for num in counter:
    heapq.heappush(heap, -num)  # Use negative for max heap

points = 0

while heap:
    # Get the number with the highest value
    highest = -heapq.heappop(heap)

    # If this number has no frequency, skip it
    if highest not in counter or counter[highest] == 0:
        continue

    # Get its frequency
    count = counter[highest]

    # Add points for this number
    points += highest * count

    # Remove this number and its neighbors from the sequence
    del counter[highest]
    if highest - 1 in counter:
        del counter[highest - 1]
    if highest + 1 in counter:
        del counter[highest + 1]

    # Push the neighbors back into the heap if they still have frequency
    if highest - 1 in counter:
        heapq.heappush(heap, -(highest - 1))
    if highest + 1 in counter:
        heapq.heappush(heap, -(highest + 1))

print(points)
