def get_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def solve():
    n = int(input())
    results = []

    # Precompute divisors for all numbers up to 10^5
    max_x = 100000
    divisors = {}
    for i in range(1, max_x + 1):
        divisors[i] = get_divisors(i)

    # Process queries
    for query_idx in range(1, n + 1):
        x, y = map(int, input().split())

        # Calculate the range to check
        start = x - y
        end = x - 1

        # Get divisors of x
        x_divisors = divisors[x]

        # Count how many divisors don't divide any number in the range
        count = 0
        valid_divisors = []
        for d in x_divisors:
            # Check if d divides any number in [start, end]
            divides_any = False
            for num in range(start, end + 1):
                if num % d == 0:
                    divides_any = True
                    break

            if not divides_any:
                valid_divisors.append(d)

        results.append(str(len(valid_divisors)))

    print("\n".join(results))

solve()
