def is_rectangle(points):
    # Extract all endpoints and count occurrences
    endpoint_counts = {}
    for x1, y1, x2, y2 in points:
        for point in [(x1, y1), (x2, y2)]:
            endpoint_counts[point] = endpoint_counts.get(point, 0) + 1

    # Check if we have exactly 4 distinct points, each appearing exactly twice
    if len(endpoint_counts) != 4 or any(count != 2 for count in endpoint_counts.values()):
        return False

    # Extract the 4 points
    points_list = list(endpoint_counts.keys())

    # Check if these points form a rectangle
    # For a rectangle with parallel sides, we need 2 distinct x's and 2 distinct y's
    x_coords = [p[0] for p in points_list]
    y_coords = [p[1] for p in points_list]

    if len(set(x_coords)) != 2 or len(set(y_coords)) != 2:
        return False

    # Extract the two distinct x and y values
    x1, x2 = sorted(set(x_coords))
    y1, y2 = sorted(set(y_coords))

    # Check if we have all four corners: (x1,y1), (x1,y2), (x2,y1), (x2,y2)
    corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}

    if corners.issubset(set(points_list)):
        return True

    return False

