import sys

def solve() -> None:
    n, t = map(int, sys.stdin.read().split())

    # Find the smallest n-digit number
    smallest_n_digit = 10 ** (n - 1)

    # Find the smallest multiple of t that is >= smallest_n_digit
    # This is equivalent to: ceil(smallest_n_digit / t) * t
    quotient = smallest_n_digit // t
    if smallest_n_digit % t == 0:
        multiple = smallest_n_digit
    else:
        multiple = (quotient + 1) * t

    # Check if this multiple has n digits
    if multiple >= smallest_n_digit and multiple <= 10 ** n - 1:
        print(multiple)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
"}

