import sys

def solve() -> None:
    n, t = map(int, sys.stdin.read().split())

    # If t > 10^n - 1, output -1
    if t > 10 ** n - 1:
        print(-1)
        return

    # Construct the smallest n-digit number as a string
    answer = '1' + '0' * (n - 1)

    # Convert to integer to check divisibility
    num = int(answer)

    # Find the smallest multiple of t >= num
    quotient = num // t
    if num % t == 0:
        answer = str(num)
    else:
        answer = str((quotient + 1) * t)

    # Ensure the answer has exactly n digits
    if len(answer) != n:
        print(-1)
    else:
        print(answer)

if __name__ == "__main__":
    solve()
"}

