def gcd(a, b):
    """Compute the greatest common divisor of a and b using Euclidean algorithm"""
    while b:
        a, b = b, a % b
    return a


def count_good_pairs(l, r, x, y):
    """Count the number of good pairs (a, b) such that GCD(a, b) = x and LCM(a, b) = y"""
    if y % x != 0:
        return 0

    k = y // x  # m * n = k where a = x*m and b = x*n
    count = 0

    # Find all divisors of k
    divisors = []
    for d in range(1, int(k**0.5) + 1):
        if k % d == 0:
            divisors.append(d)
            if d != k // d:
                divisors.append(k // d)

    # For each divisor d, check if d and k/d are coprime
    # and if x*d and x*(k/d) are within [l, r]
    for d in divisors:
        other = k // d
        if gcd(d, other) == 1:
            a1 = x * d
            a2 = x * other
            if l <= a1 <= r and l <= a2 <= r:
                count += 1
            # If d != other, also consider (other, d)
            if d != other:
                a1, a2 = x * other, x * d
                if l <= a1 <= r and l <= a2 <= r:
                    count += 1

    return count


# Read input
l, r, x, y = map(int, input().split())

# Compute answer
answer = count_good_pairs(l, r, x, y)

# Output answer
print(answer)
