def count_occurrences(s, substr):
    """Count how many times substr appears as a substring in s"""
    count = 0
    len_sub = len(substr)
    for i in range(len(s) - len_sub + 1):
        if s[i:i+len_sub] == substr:
            count += 1
    return count


