def count_occurrences(s, substr):
    """Count how many times substr appears as a substring in s"""
    count = 0
    len_sub = len(substr)
    for i in range(len(s) - len_sub + 1):
        if s[i:i+len_sub] == substr:
            count += 1
    return count


def is_lucky(subs):
    """Check if a substring is a lucky number"""
    if not subs:
        return False
    if subs[0] == '0':  # No leading zeroes
        return False
    for ch in subs:
        if ch not in {'4', '7'}:
            return False
    return True


