for mask in range(1, 1 << n):
    team = []
    valid = True

    for i in range(n):
        if mask & (1 << i):
            team.append(names[i])

    # Check if this team is valid (no conflicts)
    for i in range(len(team)):
        for j in range(i + 1, len(team)):
            if (team[i], team[j]) in conflicts:
                valid = False
                break
        if not valid:
            break

    if valid and len(team) > len(max_team):
        max_team = team

