    elif word.endswith("initis"):
        # Masculine verb
        valid_words.append(("verb", "masculine"))
    elif word.endswith("inites"):
        # Feminine verb
        valid_words.append(("verb", "feminine"))
    else:
        # Invalid word
        valid_words = []
        break

