    for i in range(1, len(valid_words)):
        if valid_words[i][1] != gender:
            print("NO")
            break
    else:
        # Check if order is: adjectives (0+) → noun (1) → verbs (0+)
        if len(valid_words) == 1:
            print("YES")
        else:
            noun_index = -1
            for i, (pos, _) in enumerate(valid_words):
