n = int(input())

if n == 1:
    print(0)
else:
    # Calculate maximum number of edges
    max_edges = n * n // 4

    # Determine which cities go in each group
    if n % 2 == 0:
        group1 = list(range(1, n // 2 + 1))
        group2 = list(range(n // 2 + 1, n + 1))
    else:
        group1 = list(range(1, (n - 1) // 2 + 1))
        group2 = list(range((n - 1) // 2 + 1, n + 1))

    # Print the result
    print(max_edges)
    for city1 in group1:
        for city2 in group2:
            print(city1, city2)
"}

