import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        freq = {}
        for num in a:
            freq[num] = freq.get(num, 0) + 1

        # Find left counts
        left = {}
        count = {}
        for num in a:
            count[num] = count.get(num, 0) + 1
            left[num] = count[num]

        # Find right counts
        right = {}
        count = {}
        for num in reversed(a):
            count[num] = count.get(num, 0) + 1
            right[num] = count[num]

        max_len = 0
        # Try all pairs (a1, a2)
        for a1 in freq:
            for a2 in freq:
                if a1 == a2:
                    # We can just take all occurrences of a1
                    max_len = max(max_len, freq[a1])
                else:
                    # Take x a1's from left and right
                    x = min(left[a1], right[a1])
                    # Take all a2's from the middle
                    y = freq[a2]

                    max_len = max(max_len, 2 * x + y)

        print(max_len)

if __name__ == "__main__":
    solve()
"}

