import sys

def solve(n):
    """Generate a string of length n with no 3-palindromes and minimal 'c's"""
    if n == 1:
        return 'a'
    if n == 2:
        return 'aa'

    # Pattern: 'aabba' avoids 3-palindromes
    # Let's use the pattern 'aabba' and repeat it

    result = []
    for i in range(n):
