def check_win(grid, i, j):
    """Check if placing an 'X' at (i, j) creates a win."""
    if grid[i][j] != '.':
        return False

    # Count consecutive 'X's in all directions
    # Left
    count = 1
    for k in range(j - 1, -1, -1):
        if grid[i][k] == 'X':
            count += 1
        else:
            break

    # Right
    for k in range(j + 1, 10):
        if grid[i][k] == 'X':
            count += 1
        else:
            break

    # Up
    for k in range(i - 1, -1, -1):
        if grid[k][j] == 'X':
            count += 1
        else:
            break

    # Down
    for k in range(i + 1, 10):
        if grid[k][j] == 'X':
            count += 1
        else:
            break

    # Diagonally up-left
    for k in range(1, 10):
        ni, nj = i - k, j - k
        if ni >= 0 and nj >= 0:
            if grid[ni][nj] == 'X':
                count += 1
            else:
                break
        else:
            break

    # Diagonally up-right
    for k in range(1, 10):
        ni, nj = i - k, j + k
        if ni >= 0 and nj < 10:
            if grid[ni][nj] == 'X':
                count += 1
            else:
                break
