for val in sorted(available.keys(), reverse=True):
    # If this value is still available, we can delete it
    if val in available:
        # Add points for deleting this value
        total_points += val * available[val]

        # Also delete adjacent values
        if (val - 1) in available:
            del available[val - 1]
        if (val + 1) in available:
            del available[val + 1]

