def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        m = int(next(data))

        directed_edges = []
        undirected_edges = []

        for _ in range(m):
            t_i = int(next(data))
            x = int(next(data)) - 1  # 0-indexed
            y = int(next(data)) - 1

            if t_i == 1:
                directed_edges.append((x, y))
            else:
                undirected_edges.append((x, y))

        # Check if directed edges alone form a cycle
        # We can do this with DFS
        visited = [False] * n
        recursion_stack = [False] * n

        def has_cycle(u):
            visited[u] = True
            recursion_stack[u] = True

            for v in range(n):
                # Only consider edges that are directed
                # We need to build an adjacency list for directed edges
                # Let's build it
                if (u, v) in directed_edges or (v, u) in directed_edges:
                    if not visited[v]:
                        if has_cycle(v):
                            return True
                    elif recursion_stack[v]:
                        return True

            recursion_stack[u] = False
            return False

        # Build adjacency list for directed edges
        adj = [[] for _ in range(n)]
        for u, v in directed_edges:
            adj[u].append(v)

        # Check for cycles
        has_cycle_flag = False
        for i in range(n):
            if not visited[i]:
                if has_cycle(i):
                    has_cycle_flag = True
                    break

        if has_cycle_flag:
            print("NO")
        else:
            # Topologically sort using Kahn's algorithm
            in_degree = [0] * n
            for u, v in directed_edges:
                in_degree[v] += 1

            queue = []
            for i in range(n):
                if in_degree[i] == 0:
                    queue.append(i)

            topo_order = []
            while queue:
                u = queue.pop(0)
                topo_order.append(u)
                for v in adj[u]:
                    in_degree[v] -= 1
                    if in_degree[v] == 0:
                        queue.append(v)

            # Now direct undirected edges from lower to higher order
            print("YES")
            print(len(directed_edges) + len(undirected_edges))

            # Print directed edges
            for u, v in directed_edges:
                print(f"{u + 1} {v + 1}")

            # Print undirected edges
            for u, v in undirected_edges:
                if topo_order.index(u) < topo_order.index(v):
                    print(f"{u + 1} {v + 1}")
                else:
                    print(f"{v + 1} {u + 1}")

solve()
