    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        m = int(next(data))

        directed_edges = []
        undirected_edges = []

        for _ in range(m):
            t_i = int(next(data))
            x = int(next(data)) - 1  # 0-indexed
            y = int(next(data)) - 1

            if t_i == 1:
                directed_edges.append((x, y))
            else:
                undirected_edges.append((x, y))

        # Check if directed edges alone form a cycle
        # We'll use Kahn's algorithm for this
        in_degree = [0] * n
        adj = [[] for _ in range(n)]

        for u, v in directed_edges:
