import sys

def has_directed_cycle(n, edges):
    """Check if there's a directed cycle in the graph."""
    graph = [[] for _ in range(n + 1)]
    for t, x, y in edges:
        if t == 1:
            graph[x].append(y)

    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)

    def dfs(node):
        if visited[node]:
            return recursion_stack[node]

        visited[node] = True
        recursion_stack[node] = True

        for neighbor in graph[node]:
            if dfs(neighbor):
                return True

        recursion_stack[node] = False
        return False

    for i in range(1, n + 1):
        if not visited[i] and dfs(i):
            return True

    return False

def topological_sort(n, edges):
    """Perform topological sort on the graph (ignoring undirected edges)."""
    graph = [[] for _ in range(n + 1)]
    for t, x, y in edges:
        if t == 1:
            graph[x].append(y)

    in_degree = [0] * (n + 1)
    for i in range(1, n + 1):
        for neighbor in graph[i]:
            in_degree[neighbor] += 1

    queue = []
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return topo_order

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        edges = []

        for _ in range(m):
            t_i = int(next(it))
            x = int(next(it))
            y = int(next(it))
            edges.append((t_i, x, y))

        if has_directed_cycle(n, edges):
            print("NO")
        else:
            print("YES")

            topo_order = topological_sort(n, edges)
