def can_move(path, pos, direction):
    """Check if a marble at position `pos` in `path` can move in the given `direction`"""
    if pos == len(path) - 1:
        return False  # Cannot move from the last square

    # Calculate the next position
    next_pos = pos + 1

    # Calculate the target coordinates
    curr_x, curr_y = 0, 0
    for i in range(pos):
