t = int(input())
for _ in range(t):
    x1, y1, x2, y2 = map(int, input().split())

    # Find the sum of all cells in the submatrix [x1, y1] to [x2, y2]
    total = 0

    # Iterate through each possible layer n
    n = max(x2, y2)
    while n >= 1:
        # Find the starting and ending positions in this layer
        start = (n - 1) ** 2 + 1
        end = n ** 2

        # The first cell of this layer is at position (n, 1)
        # The last cell of this layer is at position (n, n)

        # Find which cells of this layer are within the submatrix
        # Cells where row = n and column <= n-1
        for j in range(1, n):
            # Cell at position (n, j)
            if start + n - 1 + j <= end:
                if x1 <= n <= x2 and y1 <= j <= y2:
                    total += start + n - 1 + j

        # Cells where row <= n and column = n
        for i in range(1, n + 1):
            # Cell at position (i, n)
            if start + i - 1 <= end:
                if x1 <= i <= x2 and y1 <= n <= y2:
                    total += start + i - 1

        n -= 1

    # Format the output
    if total < 10 ** 10:
        print(total)
    else:
        print(f"...{total % (10 ** 10):010d}")
"}

