n, k = map(int, input().split())

# Function to get suffix from k-th vowel from end
# Returns suffix or None if not enough vowels

def get_suffix(line):
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Find positions of vowels from the end
    vowel_positions = []
    for i, ch in enumerate(reversed(line)):
        if ch in vowels:
            vowel_positions.append(len(line) - i - 1)

    if len(vowel_positions) >= k:
        # Get position of k-th vowel from end
        kth_vowel_pos = vowel_positions[-k]
        return line[kth_vowel_pos:]
    return None

# Function to check if lines rhyme
# Returns True if suffix matches

def rhymes(line1, line2):
    suffix1 = get_suffix(line1)
    suffix2 = get_suffix(line2)

    if suffix1 is None or suffix2 is None:
        return False
    return suffix1 == suffix2

