# Returns True if all required lines rhyme

def fits_scheme(quatrain, scheme):
    line1, line2, line3, line4 = quatrain

    if scheme == "aabb":
        return rhymes(line1, line2) and rhymes(line3, line4)
    elif scheme == "abab":
        return rhymes(line1, line3) and rhymes(line2, line4)
    elif scheme == "abba":
        return rhymes(line1, line4) and rhymes(line2, line3)
    elif scheme == "aaaa":
        return rhymes(line1, line2) and rhymes(line1, line3) and rhymes(line1, line4)
    return False

# Check each quatrain against all possible schemes
# For each quatrain, determine which schemes it fits

def get_possible_schemes(quatrain):
    line1, line2, line3, line4 = quatrain

    # Check if all lines rhyme
    all_rhymes = rhymes(line1, line2) and rhymes(line1, line3) and rhymes(line1, line4)

    if all_rhymes:
        return {"aabb", "abab", "abba", "aaaa"}

    # Check which specific schemes are possible
    possible = set()

