words = input().split()

# Define valid endings
endings = {
    ("adjective", "masculine"): "lios",
    ("adjective", "feminine"): "liala",
    ("noun", "masculine"): "etr",
    ("noun", "feminine"): "etra",
    ("verb", "masculine"): "initis",
    ("verb", "feminine"): "inites"
}

# Check if a word is valid and get its part of speech and gender
def is_valid(word):
    for (pos, gender), suffix in endings.items():
        if word.endswith(suffix):
            return (pos, gender)
    return None

# Process each word
valid_words = []
for word in words:
    result = is_valid(word)
    if result is None:
        print("NO")
        exit()
    valid_words.append(result)

# Check if all words have the same gender
gender = valid_words[0][1]
for pos, curr_gender in valid_words:
    if curr_gender != gender:
        print("NO")
        exit()

# Check if parts of speech follow the required order
adj_count = 0
noun_count = 0
verb_count = 0
for pos, _ in valid_words:
    if pos == "adjective":
        adj_count += 1
    elif pos == "noun":
        noun_count += 1
    elif pos == "verb":
        verb_count += 1

# Check order: adjectives (0+), noun (1), verbs (0+)
if noun_count != 1:
    print("NO")
    exit()

# Check that after noun, all remaining are verbs
noun_index = -1
for i, (pos, _) in enumerate(valid_words):
    if pos == "noun":
        noun_index = i
        break

for i in range(noun_index + 1, len(valid_words)):
    if valid_words[i][0] != "verb":
        print("NO")
        exit()

print("YES")
