{"code": "
n = int(input())
x0, y0 = map(int, input().split())

pieces = []
for _ in range(n):
    parts = input().split()
    pieces.append((parts[0], int(parts[1]), int(parts[2])))

# Check if a piece can attack the king and its path is not blocked
for i, (typ, px, py) in enumerate(pieces):
    # Check if this piece can attack the king
    can_attack = False
    if typ == 'B':
        # Bishop: same diagonal
        if abs(px - x0) == abs(py - y0):
            can_attack = True
    elif typ == 'R':
        # Rook: same row or column
        if px == x0 or py == y0:
            can_attack = True
    elif typ == 'Q':
        # Queen: any direction
        if px == x0 or py == y0 or abs(px - x0) == abs(py - y0):
            can_attack = True

    if not can_attack:
        continue

    # Check if path is blocked
    blocked = False
    dx = px - x0
    dy = py - y0

    # Check direction (unit step)
    if dx != 0:
        step_x = 1 if dx > 0 else -1
    else:
        step_x = 0
    if dy != 0:
        step_y = 1 if dy > 0 else -1
    else:
        step_y = 0

    # Check all other pieces
    for j, (typ2, px2, py2) in enumerate(pieces):
        if i == j:
            continue

        # Check if this piece is on the same line of attack
        if typ2 == 'B':
            # Bishop: same diagonal
            if abs(px2 - x0) == abs(py2 - y0):
                # Check if it's on the same diagonal and between the attacker and king
                if (x0 - px2) * dx < 0 and (y0 - py2) * dy < 0:
                    blocked = True
                    break
        elif typ2 == 'R':
            # Rook: same row or column
            if px2 == x0 or py2 == y0:
                # Check if it's on the same row/column and between the attacker and king
                if (x0 - px2) * dx < 0 and (y0 - py2) * dy < 0:
                    blocked = True
                    break
        elif typ2 == 'Q':
            # Queen: any direction
            if px2 == x0 or py2 == y0 or abs(px2 - x0) == abs(py2 - y0):
                # Check if it's on the same line of attack and between the attacker and king
                if (x0 - px2) * dx < 0 and (y0 - py2) * dy < 0:
                    blocked = True
                    break

    if not blocked:
        print("YES")
        exit()

print("NO")
"}

