    # Check if this piece can attack the king
    can_attack = False
    if typ == 'B':
        # Bishop: same diagonal
        if abs(px - x0) == abs(py - y0):
            can_attack = True
    elif typ == 'R':
        # Rook: same row or column
        if px == x0 or py == y0:
            can_attack = True
    elif typ == 'Q':
        # Queen: any direction
        if px == x0 or py == y0 or abs(px - x0) == abs(py - y0):
            can_attack = True

    if not can_attack:
