def is_perfect_square(x):
    s = int(x ** 0.5)
    return s * s == x

def solve():
    n = int(input())
    given = list(map(int, input().split()))

    # We need to find x_1, x_3, ..., x_{n-1}
    # Let's try to construct the sequence

    # Start with x_1 = 1 (smallest perfect square)
    x = [0] * n
    x[0] = 1  # a² = 1

    # Try to find a sequence where all partial sums are perfect squares
    for i in range(1, n):
        # Compute the next partial sum
        if i % 2 == 0:
            # i is even, x_i is given
            x[i] = given[i // 2 - 1]
            partial_sum = sum(x[:i+1])
            if not is_perfect_square(partial_sum):
                return "No"
        else:
            # i is odd, x_i needs to be found
            # Try different perfect squares for x_i
            found = False
            for j in range(1, 100000):
                next_sum = sum(x[:i]) + j*j
                if is_perfect_square(next_sum):
                    x[i] = j*j - sum(x[:i])
                    found = True
                    break
            if not found:
                return "No"

    # Check the final sum
    if not is_perfect_square(sum(x)):
        return "No"

    return "Yes" + "\n" + " ".join(map(str, x))

result = solve()
