    return s * s == x

def solve():
    n = int(input())
    given = list(map(int, input().split()))

    # We need to find x_1, x_3, ..., x_{n-1}
    # Let's work backwards from the known even-indexed values

    # Start from the last element
    x = [0] * n

    # Find perfect square for the last partial sum
    # S_n = x_1 + x_2 + ... + x_n = perfect square
    # Let's try different perfect squares for the last element
    for last_square in range(1, 100000):
        # The last partial sum is last_square
        # The previous partial sum (S_{n-1}) is last_square - x_n
        # S_{n-1} must be a perfect square
        for prev_square in range(1, 100000):
            x[n-1] = last_square - prev_square

            # Check if all previous constraints hold
            valid = True
            for i in range(n-2, -1, -1):
                if i % 2 == 0:
                    # i is even, x_i is given
                    x[i] = given[i // 2 - 1]
                    partial_sum = sum(x[:i+1])
                    if not is_perfect_square(partial_sum):
                        valid = False
                        break
                else:
                    # i is odd, x_i needs to be found
                    # The partial sum up to i is a perfect square
                    partial_sum = sum(x[:i+1])
                    if not is_perfect_square(partial_sum):
                        valid = False
                        break

            if valid:
                return "Yes" + "\n" + " ".join(map(str, x))

    return "No"

