def is_perfect_square(x):
    s = int(x ** 0.5)
    return s * s == x

def solve():
    n = int(input())
    given = list(map(int, input().split()))

    # We need to find x_1, x_3, ..., x_{n-1}

    # Start with x_1 = a²
    # Try different values for a
    for a in range(1, 100000):
        x = [0] * n
        x[0] = a * a

        # Try different values for the other odd positions
        found = True
        for i in range(1, n):
            if i % 2 == 0:
                # i is even, x_i is given
                x[i] = given[i // 2 - 1]
                partial_sum = sum(x[:i+1])
                if not is_perfect_square(partial_sum):
                    found = False
                    break
            else:
                # i is odd, x_i needs to be found
                # The partial sum up to i must be a perfect square
                # Try different values for the perfect square at position i
                found2 = False
                for b in range(a, 100000):
                    next_sum = sum(x[:i]) + b * b
                    if is_perfect_square(next_sum):
                        x[i] = b * b - sum(x[:i])
                        found2 = True
                        break
                if not found2:
                    found = False
                    break

        if found:
            # Check if the final sum is a perfect square
            if is_perfect_square(sum(x)):
