def group_sequence(sequence):
    """Group consecutive identical elements in the sequence."""
    groups = []
    count = 1
    for i in range(1, len(sequence)):
        if sequence[i] == sequence[i-1]:
            count += 1
        else:
            groups.append((sequence[i-1], count))
            count = 1
    groups.append((sequence[-1], count))
    return groups

def max_points(groups):
    """Solve the "house robber" problem on groups of consecutive identical elements."""
    n = len(groups)
    dp = [0] * n

    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return groups[0][1] * groups[0][0]

    dp[0] = groups[0][1] * groups[0][0]
    dp[1] = max(groups[0][1] * groups[0][0], groups[1][1] * groups[1][0])

    # DP transition
    for i in range(2, n):
        dp[i] = max(groups[i][1] * groups[i][0] + dp[i-2], dp[i-1])

    return dp[-1]

n = int(input())
sequence = list(map(int, input().split()))

if n == 0:
    print(0)
else:
    groups = group_sequence(sequence)
    print(max_points(groups))
