def count_divisors(n):
    """Count the number of divisors of n"""
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:
                count += 1
    return count


def solve():
    n = int(input())
    for i in range(1, n + 1):
        x, y = map(int, input().split())
        if y == 0:
            # Count all divisors of x
            print(count_divisors(x))
        else:
            # Look at range [x - y, x - 1]
            start = x - y
            end = x - 1

            # Find all divisors of x
            divisors = set()
            for d in range(1, int(x**0.5) + 1):
                if x % d == 0:
                    divisors.add(d)
                    divisors.add(x // d)

            # Check each divisor
            count = 0
            for d in divisors:
                # Check if d divides any number in [start, end]
                # This is equivalent to checking if there exists k such that d * k is in [start, end]
                # Which means: ceil(start / d) <= floor(end / d)
                ceil_start = (start + d - 1) // d  # Equivalent to math.ceil(start / d)
                floor_end = end // d

                if ceil_start <= floor_end:
                    # d divides some number in the range, reject
                    continue
                else:
                    # d does NOT divide any number in the range, accept
                    count += 1

            print(count)

if __name__ == "__main__":
    solve()
