    """Check if directed graph has a cycle using DFS"""
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            recursion_stack[node] = True

            for neighbor in graph[node]:
                if not visited[neighbor]:
                    if dfs(neighbor):
                        return True
                elif recursion_stack[neighbor]:
                    return True

            recursion_stack[node] = False
            return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i):
                return True
    return False


def topological_sort(graph, n):
    """Return topological order of directed graph"""
    visited = [False] * (n + 1)
    order = []

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                dfs(neighbor)
            order.append(node)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    return order[::-1]


