    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i):
                return True
    return False


def topological_sort(graph, n):
    """Return topological order of directed graph"""
    visited = [False] * (n + 1)
    order = []

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                dfs(neighbor)
            order.append(node)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    return order[::-1]


def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        m = int(data[index + 1])
        index += 2

        graph = [[] for _ in range(n + 1)]
        edges = []
        undirected_edges = []

        for __ in range(m):
            t_i = int(data[index])
            x = int(data[index + 1])
            y = int(data[index + 2])
            index += 3

            if t_i == 1:
                # Directed edge
                graph[x].append(y)
                edges.append((x, y, 1))  # 1 means directed
            else:
                # Undirected edge
                edges.append((x, y, 0))
                undirected_edges.append((x, y))

        # Check for cycle in directed edges
        if has_cycle(graph, n):
            results.append("NO")
        else:
            # Topological sort of directed edges
            order = topological_sort(graph, n)

            # Build order map
            order_map = {node: idx for idx, node in enumerate(order)}

            # Direct undirected edges
            for i, (x, y, type_i) in enumerate(edges):
                if type_i == 0:
                    if order_map[x] < order_map[y]:
                        edges[i] = (x, y, 1)
                    else:
                        edges[i] = (y, x, 1)

            # Output
            results.append("YES")
            for edge in edges:
                results.append(f"{edge[0]} {edge[1]}")

    sys.stdout.write("\n".join(results))

solve()

