import sys

def normalize(login):
    """Normalize a login by:
    - Converting to lowercase
    - Replacing 'o' with '0'
    - Replacing '1' with 'l'
    """
    return login.lower().replace('o', '0').replace('1', 'l')

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    new_login = data[0]
    n = int(data[1])
    existing_logins = data[2:2+n]

    normalized_new = normalize(new_login)

    for login in existing_logins:
        if normalize(login) == normalized_new:
            print("No")
            return

    print("Yes")

if __name__ == "__main__":
    main()
"}

