def solve():
    import sys
    input = sys.stdin.read().split()
    if not input:
        return
    data = iter(input)
    n = int(next(data))
    m = int(next(data))

    # Read the grid
    grid = []
    for _ in range(n):
        grid.append(next(data))

    # Find connected components of empty cells
    visited = [[False] * m for _ in range(n)]
    component_id = [[-1] * m for _ in range(n)]
    component_size = []

    current_id = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find the entire component
                queue = [(i, j)]
                visited[i][j] = True
                component_id[i][j] = current_id
                size = 1

                while queue:
                    x, y = queue.pop(0)
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if not visited[nx][ny] and grid[nx][ny] == '.':
                                visited[nx][ny] = True
                                component_id[nx][ny] = current_id
                                queue.append((nx, ny))
                                size += 1

                component_size.append(size)
                current_id += 1

    # Prepare answer
    result = [['.' for _ in range(m)] for _ in range(n)]

    # Process each '*' cell
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                # Check all 4 neighbors
                neighbors = set()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[ni][nj] == '.':
                            neighbors.add(component_id[ni][nj])

                # Sum sizes of neighboring components
                total = sum(component_size[neighbor] for neighbor in neighbors) + 1
                result[i][j] = str(total % 10)

    # Print the result
    for row in result:
        print(''.join(row))

solve()
