def is_lucky(s):
    """Check if a string is a lucky number"""
    return all(c in {'4', '7'} for c in s) and s[0] != '0'

def solve(s):
    n = len(s)
    freq = {}

    # Generate all substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if is_lucky(substr):
                freq[substr] = freq.get(substr, 0) + 1

    if not freq:
        return "-1"

    # Find maximum frequency
    max_freq = max(freq.values())

    # Find all substrings with max frequency
    max_substrings = [substr for substr, count in freq.items() if count == max_freq]

    # Return lexicographically smallest
    return min(max_substrings)

# Read input and output
s = input().strip()
print(solve(s))
